package vn.iotstar.service; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class MailService{final JavaMailSender sender; @Value("${app.mail.from:no-reply@example.com}") String from; public void send(String to,String code){var m=new SimpleMailMessage();m.setFrom(from);m.setTo(to);m.setSubject("OTP ViDu2");m.setText("Mã xác nhận của bạn: "+code);sender.send(m);}}
